// attrText returns the actual source bytes of the expression's range.
// This relies on parser.Files()[blkRange.Filename] being available.
func attrText(file *hcl.File, exprRange hcl.Range) string {
	src := file.Bytes
	if exprRange.End.Byte > len(src) {
		return fmt.Sprintf("%d:%d", exprRange.Start.Byte, exprRange.End.Byte)
	}
	return string(src[exprRange.Start.Byte:exprRange.End.Byte])
}
